fn v3_epicops_buff_window(&mut self, version, rnd, player, data, goal_data, plan) -> bool

// --- 1) 수리(리페어) 게이트 ---  epic.rs:635
let team = player.info.team;                       // PlayerState+0x930
match v3_epicops_repair_need(team, data.cache, plan) {   // -> u8
  1 => {                                            // epic.rs:637~639
        self.objective = Some(MainObjective::Repair);     // 0x41f = 7
        self.chats.push(Chat::Repair(0));                 // 태그 23, 페이로드 0
        return true;
      }
  2 => {                                            // epic.rs:642~643
        self.objective = Some(MainObjective::Repair);     // 0x41f = 7 (채팅 없음)
        return true;
      }
  _ => {}                                           // 0 및 그 외 → 아래로
}

// --- 2) 서펜 셋업 게이트 ---  epic.rs:651~658
if is_object_being_taken_by_enemy(player, data, goal_data, self, /*flag=*/true)
   && v3_serpen_contest_clear_win(version, player, data, self) {
     self.eo_serpen_punish_issues += 1;                        // 0x410, epic.rs:653
     self.objective = Some(MainObjective::Serpen {             // epic.rs:654
         phase: ObjectPhase::Setup,                            // 0x420 = 1
         with_battle: true,                                    // 0x421 = 1
     });                                                       // 0x41f = 1
     self.chats.push(Chat::SerpenSetup(0));                    // 태그 25, epic.rs:658
     return true;
}
// ※ 둘 중 하나라도 false 면(그리고 repair_need==0 이면) 아래 압박라인 경로로 간다.
//   IR 상 is_object_being_taken_by_enemy 가 false 인 경우와 clear_win 이 false 인 경우가
//   같은 블록(%35)으로 합류한다 = 단락(&&) 구조.

// --- 3) 압박 라인 채팅 경로 ---  epic.rs:664~682
let strategy = player.strategy(rnd, data.cache.game);          // sret Strategy(24B), epic.rs:664
let group_line: Option<LineType> = v3_epic_group_line(strategy.morgard_use, player, data); // epic.rs:665
if group_line.is_none() { return false; }                      // 니치 -1 검사

if self.v3_press_chat_line == group_line { return false; }     // epic.rs:666 (ne 비교, 중복 억제)

// 대변인 고르기: 슬롯 0..5 를 순서대로 훑어 첫 번째로 조건을 만족하는 슬롯
let announcer: Option<usize> = (0..5).find(|p| {               // epic.rs:667 (완전 언롤됨)
     let ent = data.cache.player_champion[team][p];            // +0x1e0, null=None → 스킵  epic.rs:668
     if ent.is_none() { return false; }
     let role = v3_epic_formation_role(strategy.morgard_use,   // epic.rs:669
                                       Position::from_index(p), player, data); // -> Option<V3EpicFormation>
     role.is_some_and(|f| !f.is_split)                         // epic.rs:670
});
// ※ V3EpicFormation{is_split:bool@+0x0, line:LineType@+0x1}, Option 니치 = is_split 바이트(2=None).
//   IR 은 (tag!=2) xor (tag&1) 로 접혀 있고 이는 정확히 is_some && !is_split 이다.
//   f.line 은 이 함수에서 쓰이지 않는다(dbg 상 poison).

if announcer == Some(player.info.position.as_index()) {        // epic.rs:672
     // 내가 대변인이면 채팅을 만든다
     let tag = if self.v3_press_chat_line.is_none() { Chat::Press } else { Chat::PressChange }; // 21 / 22, epic.rs:673
     self.chats.push(tag(group_line, 0));                      // +0x0 태그, +0x1 LineType, +0x8 usize=0
}
self.v3_press_chat_line = Some(group_line);                    // 0x41e, epic.rs:679 이후 — 항상 실행
return false;                                                  // epic.rs:682

// 반환값 정리: true 는 수리(2경로)·서펜셋업(1경로) 뿐. 압박라인 경로와 조기 이탈은 전부 false.
